// src/paginas/logeo/Cuenta.jsx

import React, { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
// import perfilData from "../../data/perfilData"; // Ya no es necesaria
import "./Cuenta.css";

// importe de la base
import Base_Main from "../../bases/Base_Main";

// Trallendo los datos de l BD
import {login} from "../../Api";

export default function CuentaPage() {

    const navigate = useNavigate();

    // Datos del usuario
    const [correo, setCorreo] = useState("");
    const [pass, setPass] = useState("");
    const [loading, setLoading] = useState(false);

    const logearUsuario = async (e) => {

        e.preventDefault();

        console.log("=== INICIO DE LOGIN ===");
        console.log("Correo:", correo);
        console.log("Pass length:", pass.length);

        if (!correo || !pass) {
            alert("Por favor completa todos los campos");
            return;
        }

        setLoading(true);

        try {
            console.log("Llamando a login API...");
            const data = await login(correo, pass);
            console.log("Respuesta:", data);

            alert(`¡Bienvenido ${data.usuario.nombre}!`);
            navigate("/perfil");
        } catch (error) {
            console.error("=== ERROR ===");
            console.error(error);
            alert(`Error: ${error.message}`);
        } finally {
            setLoading(false);
        }
    };

    const passOlvidada = () => {
        e.preventDefault(); // Importante!
        if (!correo) {
            alert("Ingresa tu correo para recuperar la contraseña");
        } else {
            alert(`Se ha enviado un correo de recuperación a ${correo}`);
        }
    };

    return (
        <Base_Main tituloPagina="Iniciar Sesión">
            <div className="cuenta-content">
                <form className="cuenta-form" onSubmit={logearUsuario}>
                    <table>
                        <tbody>
                            <tr>
                                <td>Correo</td>
                                <td><input
                                type="email"
                                name="correo"
                                value={correo}
                                onChange={(e) => setCorreo(e.target.value)}
                                required/></td>
                            </tr>
                            <tr>
                                <td>Contraseña</td>
                                <td><input
                                type="password"
                                name="pass"
                                value={pass}
                                onChange={(e) => setPass(e.target.value)}
                                required/></td>
                            </tr>
                        </tbody>
                    </table>

                    <p><a href="#" onClick={passOlvidada}>¿Olvidaste tu contraseña?</a></p>
                    <button type="submit" className="cuenta-btn" disabled={loading}>
                        {loading ? "Iniciando sesión..." : "Iniciar Sesión"}
                    </button>

                    <p className="cuenta-login-text">¿Aún no tienes cuenta?</p>
                    <Link to="/registro">Registrarse</Link>
                </form>
            </div>
        </Base_Main>
    );
}
